const easternValues = [
  {name:{en:'Patient first',es:'El paciente primero'},action:{en:'See the whole person, listen without judgment and build a realistic path toward better health—not merely a completed visit.',es:'Ver a la persona completa, escuchar sin juzgar y construir un camino realista hacia una mejor salud, no simplemente completar una consulta.'},concept:{en:'Putting the patient first means understanding health, family, culture, access, fears and goals before coordinating the next step. Eastern Medical seeks a long-term relationship in which prevention, responsible medication use, nutrition, movement, education and counseling support quality of life.',es:'Poner al paciente primero significa comprender su salud, familia, cultura, acceso, temores y objetivos antes de coordinar el próximo paso. Eastern Medical busca una relación a largo plazo donde la prevención, el uso responsable de medicamentos, la nutrición, el movimiento, la educación y el counseling apoyen la calidad de vida.'},practices:{en:['Listen actively and confirm what matters most to the patient','Protect privacy, dignity, language preference and informed participation','Facilitate annual physicals, screenings and timely follow-up','Encourage discussion with the clinician about medication burden, interactions and safer alternatives—never tell the patient to stop medication','Connect the patient with qualified nutrition, healthy-weight, physical-activity or counseling resources when appropriate','Remove practical barriers through scheduling, transportation, coverage guidance and documented follow-through'],es:['Escuchar activamente y confirmar qué es lo más importante para el paciente','Proteger privacidad, dignidad, preferencia de idioma y participación informada','Facilitar exámenes físicos anuales, evaluaciones preventivas y seguimiento oportuno','Promover que el paciente converse con la proveedora sobre carga de medicamentos, interacciones y alternativas seguras; nunca indicarle que suspenda un medicamento','Conectar al paciente con recursos cualificados de nutrición, peso saludable, actividad física o counseling cuando corresponda','Reducir barreras prácticas mediante citas, transporte, orientación de cobertura y seguimiento documentado']},example:{en:'A patient with several medications says they feel tired and wants to stop one. The employee listens, does not interpret the symptom or change treatment, documents the concern and arranges a provider review. The visit can also explore prevention, nutrition, movement and counseling needs.',es:'Un paciente que toma varios medicamentos dice sentirse cansado y quiere suspender uno. El colaborador escucha, no interpreta el síntoma ni cambia el tratamiento, documenta la inquietud y coordina una revisión con la proveedora. La consulta también puede explorar prevención, nutrición, movimiento y necesidades de counseling.'},boundary:{en:'Only a licensed clinician may change medication, prescribe a diet as treatment, diagnose a behavioral condition or establish a clinical counseling plan.',es:'Solo un profesional clínico licenciado puede cambiar medicamentos, prescribir una dieta como tratamiento, diagnosticar una condición conductual o establecer un plan clínico de counseling.'}},
  {name:{en:'Prevention',es:'Prevención'},action:{en:'Act before avoidable problems become crises through checkups, screening, education and continuity.',es:'Actuar antes de que los problemas evitables se conviertan en crisis mediante chequeos, evaluaciones, educación y continuidad.'},concept:{en:'Preventive medicine is a culture, not a single annual appointment. It combines age- and risk-appropriate evaluation, vaccination, laboratory or diagnostic follow-up when ordered, attention to nutrition and activity, and consistent monitoring of chronic conditions.',es:'La medicina preventiva es una cultura, no una sola cita anual. Combina evaluación apropiada según edad y riesgo, vacunación, seguimiento de laboratorios o diagnósticos cuando se ordenen, atención a nutrición y actividad y monitoreo constante de condiciones crónicas.'},practices:{en:['Identify overdue annual physicals and approved preventive activities','Explain preparation and follow-up steps using verified information','Close gaps in referrals, diagnostics, laboratory work and chronic-care visits','Reinforce clinician-approved goals for nutrition, movement, sleep and tobacco avoidance','Contact the patient through approved outreach workflows and document the outcome'],es:['Identificar exámenes físicos anuales y actividades preventivas pendientes','Explicar preparación y seguimiento usando información verificada','Cerrar brechas de referidos, diagnósticos, laboratorios y seguimiento de condiciones crónicas','Reforzar objetivos aprobados por la proveedora sobre nutrición, movimiento, sueño y evitar tabaco','Contactar al paciente mediante flujos aprobados y documentar el resultado']},example:{en:'After an annual physical, the work is not finished. The team tracks ordered studies, the provider review, referrals and the next preventive milestone so the patient does not disappear between steps.',es:'Después del examen físico anual, el trabajo no termina. El equipo rastrea estudios ordenados, revisión de la proveedora, referidos y el próximo hito preventivo para que el paciente no se pierda entre pasos.'},boundary:{en:'Employees promote access and adherence to approved plans; clinicians determine which screenings, tests and interventions are appropriate.',es:'Los colaboradores promueven acceso y cumplimiento de planes aprobados; el personal clínico determina qué evaluaciones, pruebas e intervenciones corresponden.'}},
  {name:{en:'Integrity',es:'Integridad'},action:{en:'Tell the truth, protect confidentiality and distinguish verified facts from assumptions.',es:'Decir la verdad, proteger la confidencialidad y distinguir los hechos verificados de las suposiciones.'},concept:{en:'Integrity protects both the patient and the organization. It means accurate documentation, honest expectations, secure handling of information and immediate correction when something is uncertain or wrong.',es:'La integridad protege al paciente y a la organización. Significa documentación precisa, expectativas honestas, manejo seguro de información y corrección inmediata cuando algo sea incierto o incorrecto.'},practices:{en:['Verify identity before discussing protected information','Never invent availability, benefits, diagnoses, results or expected outcomes','Document what happened, who owns the next action and when follow-up is due','Disclose uncertainty and check the approved source before answering','Escalate errors, privacy concerns and safety issues promptly'],es:['Verificar identidad antes de hablar de información protegida','Nunca inventar disponibilidad, beneficios, diagnósticos, resultados ni desenlaces','Documentar qué ocurrió, quién es responsable y cuándo corresponde seguimiento','Reconocer la incertidumbre y revisar la fuente aprobada antes de responder','Escalar rápidamente errores, inquietudes de privacidad y asuntos de seguridad']},example:{en:'If the employee cannot confirm whether a service is available at Hialeah, the honest response is to verify the directory and call back—not to guess in order to keep the patient satisfied.',es:'Si el colaborador no puede confirmar si un servicio está disponible en Hialeah, la respuesta íntegra es verificar el directorio y devolver la llamada, no adivinar para complacer al paciente.'},boundary:{en:'Good intentions never justify sharing information without authorization or making an unsupported promise.',es:'Las buenas intenciones nunca justifican compartir información sin autorización ni hacer una promesa sin respaldo.'}},
  {name:{en:'Education & counseling',es:'Educación y counseling'},action:{en:'Give the patient understandable tools to participate in care and connect them with qualified support.',es:'Dar al paciente herramientas comprensibles para participar en su cuidado y conectarlo con apoyo cualificado.'},concept:{en:'Education turns instructions into understanding. Counseling may include motivational support, healthy-habit coaching, navigation and clinician-directed behavioral or nutritional services. The goal is not to lecture; it is to help the patient identify achievable steps and know when professional support is needed.',es:'La educación convierte instrucciones en comprensión. El counseling puede incluir apoyo motivacional, acompañamiento de hábitos saludables, navegación y servicios conductuales o nutricionales dirigidos por profesionales. El objetivo no es sermonear, sino ayudar al paciente a identificar pasos alcanzables y saber cuándo necesita apoyo profesional.'},practices:{en:['Use plain language and the patient’s preferred language','Ask the patient to explain the next step in their own words','Provide only approved educational materials','Use open questions to understand barriers to diet, exercise, medication adherence or follow-up','Connect to a provider, nutrition professional or behavioral-health resource when individualized counseling is needed'],es:['Usar lenguaje sencillo y el idioma preferido del paciente','Pedir al paciente que explique el próximo paso con sus propias palabras','Entregar solamente materiales educativos aprobados','Usar preguntas abiertas para comprender barreras de dieta, ejercicio, adherencia o seguimiento','Conectar con una proveedora, profesional de nutrición o recurso de salud conductual cuando se necesite counseling individualizado']},example:{en:'Instead of saying “you need to eat better,” ask what makes balanced meals difficult, reinforce the clinician’s approved plan and connect the patient to qualified nutritional support.',es:'En lugar de decir “tiene que comer mejor”, pregunta qué dificulta una alimentación balanceada, refuerza el plan aprobado por la proveedora y conecta al paciente con apoyo nutricional cualificado.'},boundary:{en:'Non-clinical education must not become diagnosis, psychotherapy, individualized medical nutrition therapy or treatment advice.',es:'La educación no clínica no debe convertirse en diagnóstico, psicoterapia, terapia nutricional médica individualizada ni recomendaciones de tratamiento.'}},
  {name:{en:'Teamwork',es:'Trabajo en equipo'},action:{en:'Coordinate across roles so the patient experiences one clear and accountable path.',es:'Coordinar entre roles para que el paciente viva un camino claro y con responsables.'},concept:{en:'Modern care depends on clinical, administrative, diagnostic, referral, insurance and support teams. Teamwork means sharing the minimum necessary information in approved systems and keeping responsibility until the receiving team accepts the handoff.',es:'La atención moderna depende de equipos clínicos, administrativos, diagnósticos, de referidos, seguros y apoyo. Trabajo en equipo significa compartir la información mínima necesaria en sistemas aprobados y mantener responsabilidad hasta que el equipo receptor acepte la transición.'},practices:{en:['Explain to the patient why another team is becoming involved','Document the need, urgency stated by the patient and expected next step','Confirm ownership instead of sending an untracked message','Follow up when the handoff is not acknowledged','Respect professional scope and ask for help early'],es:['Explicar al paciente por qué participará otro equipo','Documentar la necesidad, urgencia expresada por el paciente y próximo paso esperado','Confirmar responsable en vez de enviar un mensaje sin seguimiento','Dar seguimiento cuando la transición no sea aceptada','Respetar el alcance profesional y pedir ayuda a tiempo']},example:{en:'A coverage barrier affecting a medical appointment requires consent, a documented handoff to Seven Insurance when appropriate and continued medical-office ownership of the appointment—not abandonment of the patient.',es:'Una barrera de cobertura que afecta una cita médica requiere consentimiento, transición documentada a Seven Insurance cuando corresponda y que la oficina médica mantenga responsabilidad sobre la cita, no abandonar al paciente.'},boundary:{en:'Teamwork does not allow access to records without a work-related need or transfer clinical decisions to unlicensed staff.',es:'El trabajo en equipo no permite acceder a expedientes sin necesidad laboral ni transferir decisiones clínicas a personal no licenciado.'}},
  {name:{en:'Continuous quality',es:'Calidad continua'},action:{en:'Measure, learn and improve every process that affects safety, access and patient trust.',es:'Medir, aprender y mejorar cada proceso que afecte seguridad, acceso y confianza.'},concept:{en:'Quality is the daily discipline of noticing where patients encounter delays, confusion, repeated work or unsafe gaps, then improving the process with evidence. Feedback is treated as information for learning, not as a reason to blame.',es:'La calidad es la disciplina diaria de identificar dónde el paciente enfrenta demoras, confusión, trabajo repetido o brechas inseguras y mejorar el proceso con evidencia. La retroalimentación se usa para aprender, no para culpar.'},practices:{en:['Document outcomes consistently so trends can be measured','Review missed follow-ups, complaints and repeated barriers','Correct inaccurate educational or directory information quickly','Standardize successful workflows across offices when appropriate','Report safety events and participate honestly in improvement work'],es:['Documentar resultados de forma consistente para medir tendencias','Revisar seguimientos perdidos, quejas y barreras repetidas','Corregir rápidamente información educativa o de directorio incorrecta','Estandarizar flujos exitosos entre sedes cuando corresponda','Reportar eventos de seguridad y participar honestamente en mejoras']},example:{en:'If patients repeatedly miss a diagnostic study because preparation instructions are unclear, the team revises the approved script, trains staff and measures whether completion improves.',es:'Si los pacientes pierden repetidamente un estudio diagnóstico porque las instrucciones de preparación no están claras, el equipo revisa el guion aprobado, capacita al personal y mide si mejora el cumplimiento.'},boundary:{en:'Process improvement must protect privacy, preserve records and follow clinical, compliance and approval requirements.',es:'La mejora de procesos debe proteger privacidad, conservar registros y cumplir requisitos clínicos, de cumplimiento y aprobación.'}},
];

