const serviceRoutingLessons = [
  {title:['The Eastern service ecosystem','El ecosistema de servicios Eastern'],intro:['Every campaign, call, visit or CRM record must become an owned next step. Learn the common routing pipeline and how to prevent a lead from becoming an untracked transfer.','Toda campaña, llamada, visita o registro de CRM debe convertirse en un próximo paso con responsable. Aprende el flujo común y cómo evitar que un lead se convierta en una transferencia sin seguimiento.'],objectives:[['Identify the primary need and the correct owner','Identificar la necesidad principal y el responsable correcto'],['Use permission, minimum necessary data and an approved workflow','Usar permiso, datos mínimos y un flujo aprobado'],['Close the loop with ownership and follow-up','Cerrar el ciclo con responsabilidad y seguimiento']],routingFlow:true,routingKeys:['insurance','medical','chronic','allergy','aesthetics','research'],sections:[['A lead is not complete when it is sent','Un lead no termina cuando se envía','A handoff is complete only when the receiving team accepts ownership, the next action is documented and the person knows what to expect.','Una transición termina solamente cuando el equipo receptor acepta responsabilidad, se documenta la próxima acción y la persona sabe qué esperar.']]},
  {title:['Seven Insurance leads','Leads de Seven Insurance'],intro:['Recognize a coverage opportunity and connect it to a licensed agent without making an insurance promise.','Reconoce una oportunidad de cobertura y conéctala con un agente licenciado sin hacer promesas de seguro.'],objectives:[['Recognize insurance intent','Reconocer intención de seguro'],['Document consent and campaign source','Documentar permiso y origen de campaña'],['Use the approved handoff language','Usar el lenguaje aprobado de transición']],routingKeys:['insurance'],sections:[['Licensed ownership','Responsabilidad licenciada','Only the licensed insurance team evaluates plan options, eligibility and enrollment actions.','Solamente el equipo licenciado evalúa opciones, elegibilidad y acciones de inscripción.']]},
  {title:['Medical care and location routing','Medicina y canalización por sede'],intro:['Match the adult patient’s need with Coral Way, Hialeah or Fort Myers and verify the requested service before scheduling.','Relaciona la necesidad del paciente adulto con Coral Way, Hialeah o Fort Myers y verifica el servicio antes de agendar.'],objectives:[['Choose the correct geographic location','Escoger la sede geográfica correcta'],['Capture scheduling and authorization facts','Capturar datos de cita y autorización'],['Apply the emergency and scope boundaries','Aplicar límites de emergencia y alcance']],routingKeys:['medical'],sections:[['Location is part of the service','La sede es parte del servicio','A correct medical referral includes the correct entity, location, payer, provider and live capacity.','Un referido médico correcto incluye entidad, sede, pagador, proveedor y capacidad vigente.']]},
  {title:['Chronic Care coordination','Coordinación de Chronic Care'],intro:['A chronic condition is generally ongoing, requires continuing medical attention or limits daily activities. Frontline staff recognize patterns; the Chronic Care team confirms qualification.','Una condición crónica generalmente es continua, requiere atención médica constante o limita actividades diarias. El personal de primera línea reconoce patrones; Chronic Care confirma la cualificación.'],objectives:[['Recognize possible chronic-care candidates','Reconocer posibles candidatos'],['Explain the specialized department safely','Explicar el departamento especializado de forma segura'],['Create a permissioned referral without diagnosing','Crear un referido con permiso sin diagnosticar']],routingKeys:['chronic'],sections:[['Examples, not diagnoses','Ejemplos, no diagnósticos','Possible signals include hypertension, diabetes, COPD or asthma, cardiovascular disease, chronic kidney disease, arthritis, depression, cancer and other ongoing conditions. Two diagnoses alone do not establish eligibility.','Posibles señales incluyen hipertensión, diabetes, EPOC o asma, enfermedad cardiovascular, enfermedad renal crónica, artritis, depresión, cáncer y otras condiciones continuas. Dos diagnósticos por sí solos no establecen elegibilidad.']]},
  {title:['Allergy and immunology services','Servicios de alergia e inmunología'],intro:['Route allergy and immunology requests to the specialized team while protecting the boundary between scheduling and clinical advice.','Canaliza solicitudes de alergia e inmunología al equipo especializado, respetando el límite entre citas y consejo clínico.'],objectives:[['Recognize an allergy-service request','Reconocer una solicitud de alergia'],['Verify location, order and coverage requirements','Verificar sede, orden y cobertura'],['Escalate severe reactions as emergencies','Escalar reacciones severas como emergencias']],routingKeys:['allergy'],sections:[['Do not clinically triage','No realizar triaje clínico','Employees coordinate access; qualified clinicians determine testing and treatment.','Los colaboradores coordinan acceso; profesionales cualificados determinan pruebas y tratamiento.']]},
  {title:['Aesthetics and wellness leads','Leads de estética y bienestar'],intro:['Convert interest into a documented consultation without overstating price, candidacy, outcomes or complimentary benefits.','Convierte el interés en una consulta documentada sin exagerar precio, candidatura, resultados ni beneficios complementarios.'],objectives:[['Identify the service of interest','Identificar el servicio de interés'],['Capture consent and campaign attribution','Capturar permiso y atribución de campaña'],['Set an honest consultation expectation','Establecer una expectativa honesta de consulta']],routingKeys:['aesthetics'],sections:[['Consultation before promise','Consulta antes de prometer','The right conversion is an informed consultation with qualified staff—not a guaranteed procedure or result.','La conversión correcta es una consulta informada con personal cualificado, no un procedimiento o resultado garantizado.']]},
  {title:['Eastern Medical Research','Eastern Medical Research'],intro:['Understand how an approved study moves from patient identification and Call Center outreach to protocol pre-screening, consent, screening, enrollment and follow-up.','Comprende cómo un estudio aprobado pasa de identificar pacientes y contactar por Call Center a pre-screening, consentimiento, screening, inscripción y seguimiento.'],objectives:[['Explain the role of Research in Fort Myers','Explicar la función de Research en Fort Myers'],['Protect voluntary participation and protocol controls','Proteger la participación voluntaria y los controles del protocolo'],['Route a possible participant to the research coordinator','Canalizar un posible participante al coordinador']],routingKeys:['research'],sections:[['The operating sequence','La secuencia operativa','Approved study and criteria → authorized patient list → approved Call Center script → protocol pre-screen → informed consent and screening → enrollment/randomization when eligible → study visits and final safety follow-up.','Estudio y criterios aprobados → lista autorizada de pacientes → guion aprobado de Call Center → pre-screen según protocolo → consentimiento informado y screening → inscripción/aleatorización si cualifica → visitas y seguimiento final de seguridad.']]},
  {title:['Routing practicum','Práctica de canalización'],intro:['Apply the complete process to mixed leads, choose one primary owner and document every secondary opportunity without losing the original request.','Aplica el proceso completo a leads mixtos, escoge un responsable principal y documenta oportunidades secundarias sin perder la solicitud original.'],objectives:[['Prioritize safety and the primary need','Priorizar seguridad y necesidad principal'],['Choose the correct owner and channel','Escoger responsable y canal correctos'],['Confirm acceptance and follow-up','Confirmar aceptación y seguimiento']],routingFlow:true,routingKeys:['insurance','medical','chronic','allergy','aesthetics','research'],sections:[['Primary need first','Primero la necesidad principal','A person may have several opportunities. Resolve or route the stated need first, ask permission before introducing another service and create separate trackable tasks when different teams are involved.','Una persona puede tener varias oportunidades. Resuelve o canaliza primero la necesidad expresada, pide permiso antes de presentar otro servicio y crea tareas separadas y rastreables cuando intervengan equipos distintos.']]},
];

